## Code Example
```javascript
// Example: useBatteryStream hook (JS side)
import { useEffect, useState } from 'react';
import { NativeEventEmitter, NativeModules } from 'react-native';
const { BatteryWatcher } = NativeModules;
const emitter = new NativeEventEmitter(BatteryWatcher);

export function useBatteryStream() {
  const [state, setState] = useState({ level: -1, ts: 0, belowThreshold: false });
  useEffect(() => {
    const sub = emitter.addListener('BatteryUpdate', (payload) => {
      setState(payload);
    });
    return () => sub.remove();
  }, []);
  return state;
}
```

